import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as conv from "../runtime/conv.ts";
import * as token from "./token.ts";

// Vectors are generated by ts/tools/gen-html-vectors (command "token") from Go's real
// html tokenizer. Byte values are either a JSON string (the bytes are valid UTF-8) or
// {"hex": "..."} (the bytes are not valid UTF-8). Documents with a string input are the
// "valid UTF-8" group; documents with a hex input are the "invalid UTF-8" group.
//
// Strings that Go builds from bytes (Token.Data, attribute keys and values, Token.String)
// are compared with the string of the same bytes. For valid input the strings must be
// equal byte for byte. For invalid input a JS string cannot hold the invalid bytes, so
// the expected value is conv.StringFromBytes(goBytes), the lossy result that the port
// returns. The two groups are separate tests. Raw and Text bytes are compared exactly in
// both groups.

type Enc = string | { hex: string };

interface HighTok {
  0: number; // type
  1: number; // DataAtom
  2: Enc; // Data
  3: [string, Enc, Enc][]; // namespace, key, value
  4: Enc; // Raw, copied before Token
  5: Enc; // Token.String
}

type LowTok = [number, Enc, Enc] | [number, Enc, Enc, boolean, [Enc, Enc, boolean][]];

interface FragTok {
  0: number; // type
  1: Enc; // Token.String
}

interface TokDoc {
  name: string;
  input: Enc;
  high: HighTok[];
  highErr: string | null;
  low: LowTok[];
  lowErr: string | null;
  frag: Record<string, [FragTok[], string | null]>;
}

interface TokVectors {
  goVersion: string;
  corpus: number;
  docs: TokDoc[];
}

const vectors: TokVectors = JSON.parse(
  readFileSync(new URL("./testdata/token_vectors.json", import.meta.url), "utf8")
);

// bytesOf returns the bytes of an encoded Go byte string, as a fresh array.
function bytesOf(v: Enc): Uint8Array {
  if (typeof v === "string") {
    return conv.BytesFromString(v);
  }
  return new Uint8Array(Buffer.from(v.hex, "hex"));
}

// isValid reports whether an encoded value is valid UTF-8 (a JSON string).
function isValid(v: Enc): boolean {
  return typeof v === "string";
}

// expectExact is the expected string for a value from valid UTF-8 input. It is the
// Go string itself. A hex-encoded value here would be a vector error, reported as such.
function expectExact(v: Enc): string {
  if (typeof v !== "string") {
    throw new Error("vector error: hex-encoded value in a valid UTF-8 document");
  }
  return v;
}

// expectLossy is the expected string for a value from invalid input: the Go bytes after
// the lossy round trip of a JS string (conv.BytesFromString(conv.StringFromBytes(goBytes))).
function expectLossy(v: Enc): string {
  return conv.StringFromBytes(bytesOf(v));
}

function bytesEqual(got: Uint8Array, want: Enc): boolean {
  return Buffer.from(got).equals(Buffer.from(bytesOf(want)));
}

// collect runs check on every document of the group and reports every mismatch.
function collect(docs: TokDoc[], check: (d: TokDoc, fails: string[]) => void): void {
  const fails: string[] = [];
  for (const d of docs) {
    try {
      check(d, fails);
    } catch (e) {
      fails.push(d.name + ": threw " + String(e));
    }
  }
  assert.equal(fails.length, 0, fails.slice(0, 20).join("\n") + "\n(" + fails.length + " failures)");
}

function errOf(e: Error | null): string | null {
  return e === null ? null : e.message;
}

// checkHigh replays the high-level loop (Next, Raw, Token) of one document.
function checkHigh(d: TokDoc, fails: string[], str: (v: Enc) => string): void {
  const zz = token.NewTokenizer(bytesOf(d.input));
  let i = 0;
  for (;;) {
    const tt = zz.Next();
    if (tt === token.ErrorToken) {
      break;
    }
    const want = d.high[i];
    if (want === undefined) {
      fails.push(d.name + ": high: extra token " + i);
      return;
    }
    if (!bytesEqual(zz.Raw(), want[4])) {
      fails.push(d.name + ": high[" + i + "] raw mismatch");
    }
    const t = zz.Token();
    if (t.Type !== want[0]) {
      fails.push(d.name + ": high[" + i + "] type " + t.Type + " want " + want[0]);
    }
    if (t.DataAtom !== want[1]) {
      fails.push(d.name + ": high[" + i + "] atom " + t.DataAtom + " want " + want[1]);
    }
    if (t.Data !== str(want[2])) {
      fails.push(d.name + ": high[" + i + "] data " + JSON.stringify(t.Data) + " want " + JSON.stringify(str(want[2])));
    }
    const gotAttrs = t.Attr.map((a) => [a.Namespace, a.Key, a.Val]);
    const wantAttrs = want[3].map(([ns, k, v]) => [ns, str(k), str(v)]);
    if (JSON.stringify(gotAttrs) !== JSON.stringify(wantAttrs)) {
      fails.push(d.name + ": high[" + i + "] attrs " + JSON.stringify(gotAttrs) + " want " + JSON.stringify(wantAttrs));
    }
    if (t.String() !== str(want[5])) {
      fails.push(d.name + ": high[" + i + "] String " + JSON.stringify(t.String()) + " want " + JSON.stringify(str(want[5])));
    }
    i++;
  }
  if (i !== d.high.length) {
    fails.push(d.name + ": high: " + i + " tokens, want " + d.high.length);
  }
  const e = errOf(zz.Err());
  if (e !== d.highErr) {
    fails.push(d.name + ": high error " + JSON.stringify(e) + " want " + JSON.stringify(d.highErr));
  }
}

// checkLow replays the low-level loop (Next, Raw, Text or TagName and TagAttr).
function checkLow(d: TokDoc, fails: string[]): void {
  const z = token.NewTokenizer(bytesOf(d.input));
  let i = 0;
  for (;;) {
    const tt = z.Next();
    if (tt === token.ErrorToken) {
      break;
    }
    const want = d.low[i];
    if (want === undefined) {
      fails.push(d.name + ": low: extra token " + i);
      return;
    }
    if (want[0] !== tt) {
      fails.push(d.name + ": low[" + i + "] type " + tt + " want " + want[0]);
    }
    if (!bytesEqual(z.Raw(), want[1])) {
      fails.push(d.name + ": low[" + i + "] raw mismatch");
    }
    if (tt === token.TextToken || tt === token.CommentToken || tt === token.DoctypeToken) {
      if (want.length !== 3 || !bytesEqual(z.Text(), want[2] as Enc)) {
        fails.push(d.name + ": low[" + i + "] text mismatch");
      }
    } else {
      const [name, hasAttr] = z.TagName();
      const tag = want as [number, Enc, Enc, boolean, [Enc, Enc, boolean][]];
      if (!bytesEqual(name, tag[2]) || hasAttr !== tag[3]) {
        fails.push(d.name + ": low[" + i + "] tag name/hasAttr mismatch");
      }
      const got: [Uint8Array, Uint8Array, boolean][] = [];
      let more = hasAttr;
      while (more) {
        const [k, v, m] = z.TagAttr();
        got.push([k, v, m]);
        more = m;
      }
      if (got.length !== tag[4].length) {
        fails.push(d.name + ": low[" + i + "] " + got.length + " attrs, want " + tag[4].length);
      } else {
        for (let j = 0; j < got.length; j++) {
          const [gk, gv, gm] = got[j]!;
          const [wk, wv, wm] = tag[4][j]!;
          if (!bytesEqual(gk, wk) || !bytesEqual(gv, wv) || gm !== wm) {
            fails.push(d.name + ": low[" + i + "] attr " + j + " mismatch");
          }
        }
      }
    }
    i++;
  }
  if (i !== d.low.length) {
    fails.push(d.name + ": low: " + i + " tokens, want " + d.low.length);
  }
  const e = errOf(z.Err());
  if (e !== d.lowErr) {
    fails.push(d.name + ": low error " + JSON.stringify(e) + " want " + JSON.stringify(d.lowErr));
  }
}

// checkFrag replays NewTokenizerFragment for each recorded context tag.
function checkFrag(d: TokDoc, fails: string[], str: (v: Enc) => string): void {
  for (const [ctx, [wantToks, wantErr]] of Object.entries(d.frag)) {
    const z = token.NewTokenizerFragment(bytesOf(d.input), ctx);
    let i = 0;
    for (;;) {
      const tt = z.Next();
      if (tt === token.ErrorToken) {
        break;
      }
      const t = z.Token();
      const want = wantToks[i];
      if (want === undefined) {
        fails.push(d.name + ": frag " + ctx + ": extra token " + i);
        break;
      }
      if (t.Type !== want[0]) {
        fails.push(d.name + ": frag " + ctx + "[" + i + "] type " + t.Type + " want " + want[0]);
      }
      if (t.String() !== str(want[1])) {
        fails.push(d.name + ": frag " + ctx + "[" + i + "] String " + JSON.stringify(t.String()) + " want " + JSON.stringify(str(want[1])));
      }
      i++;
    }
    if (i !== wantToks.length) {
      fails.push(d.name + ": frag " + ctx + ": " + i + " tokens, want " + wantToks.length);
    }
    const e = errOf(z.Err());
    if (e !== wantErr) {
      fails.push(d.name + ": frag " + ctx + " error " + JSON.stringify(e) + " want " + JSON.stringify(wantErr));
    }
  }
}

function checkDoc(d: TokDoc, fails: string[], str: (v: Enc) => string): void {
  checkHigh(d, fails, str);
  checkLow(d, fails);
  checkFrag(d, fails, str);
}

const validDocs = vectors.docs.filter((d) => isValid(d.input));
const invalidDocs = vectors.docs.filter((d) => !isValid(d.input));

test("token vectors: corpus size", () => {
  assert.equal(vectors.docs.length, vectors.corpus);
  assert.ok(vectors.docs.length >= 400, "corpus has " + vectors.docs.length + " documents");
  assert.ok(validDocs.length > 0 && invalidDocs.length > 0, "both UTF-8 groups are non-empty");
});

test("token vectors (valid UTF-8 input): strings match Go byte for byte", () => {
  collect(validDocs, (d, fails) => checkDoc(d, fails, expectExact));
});

test("token vectors (invalid UTF-8 input): strings match Go after the lossy conversion", () => {
  // The JS string cannot hold the invalid bytes, so each expected string is
  // conv.StringFromBytes of Go's bytes (see expectLossy). Raw and Text are still exact.
  collect(invalidDocs, (d, fails) => checkDoc(d, fails, expectLossy));
});
